// Equally likely outcome grid for two dice: every cell is one ordered pair.
// Two-argument size() fixes the output box, so the declared 4/3 is exact.
size(480,360);
pen g = gray(0.65) + 0.7;
pen hl = rgb(0.82,0.24,0.20) + 0;
for (int i = 0; i <= 6; ++i) {
  draw((i,0)--(i,6), g);
  draw((0,i)--(6,i), g);
}
for (int k = 1; k <= 6; ++k) {
  filldraw((k-1,6-k)--(k,6-k)--(k,7-k)--(k-1,7-k)--cycle, hl);
}
label("6 shaded of 36", (3,6.6), N);
label("6 unshaded of 36", (3,-0.6), S);
dot((6.3,3), black+2pt);

// Geometric probability: probability is an area ratio on a uniformly hit region.
// Two-argument size() fixes the output box, so the declared 1.6 is exact.
size(480,300);
pen t = black + 1.2;
filldraw((0,0)--(6,0)--(6,6)--(0,6)--cycle, gray(0.93));
draw((0,0)--(6,0)--(6,6)--(0,6)--cycle, t);
draw(Circle((3,3),1.2), t);
draw(Circle((3,3),2.4), t);
filldraw(Circle((3,3),2.4)--Circle((3,3),1.2)--cycle, rgb(0.82,0.24,0.20)+0.3);
filldraw(Circle((3,3),1.2)--cycle, rgb(0.20,0.45,0.75)+0.3);
dot((3,3), black+2pt);
label("inner region", (3,0.6), N);
label("ring between the two circles", (3,1.8), N);
label("outer region", (5.1,2.2), E);
